function parseDecimal(value, name) {
  if (!/^\d+(?:\.\d+)?$/.test(value ?? '')) {
    throw new Error(`${name} must be a nonnegative decimal number`);
  }

  const [whole, fraction = ''] = value.split('.');
  return {
    coefficient: BigInt(whole + fraction),
    scale: fraction.length,
  };
}

function roundHalfUp(numerator, denominator) {
  return (2n * numerator + denominator) / (2n * denominator);
}

function dollars(cents) {
  return `$${cents / 100n}.${(cents % 100n).toString().padStart(2, '0')}`;
}

try {
  const args = process.argv.slice(2);
  if (args.length !== 3 || args[1] !== '--percent') {
    throw new Error('Usage: node bin/tipcalc.js <bill> --percent <percentage>');
  }

  const bill = parseDecimal(args[0], 'Bill');
  const percent = parseDecimal(args[2], 'Percentage');
  const billDenominator = 10n ** BigInt(bill.scale);
  const tipDenominator = 10n ** BigInt(bill.scale + percent.scale);
  const tipCents = roundHalfUp(bill.coefficient * percent.coefficient, tipDenominator);
  const billCents = roundHalfUp(bill.coefficient * 100n, billDenominator);
  const totalCents = billCents + tipCents;

  process.stdout.write(`Tip: ${dollars(tipCents)}  Total: ${dollars(totalCents)}\n`);
} catch (error) {
  process.stderr.write(`Error: ${error.message}\n`);
  process.exitCode = 1;
}
const test = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const path = require('node:path');

const command = path.join(__dirname, '..', 'bin', 'tipcalc.js');

function run(...args) {
  return spawnSync(process.execPath, [command, ...args], { encoding: 'utf8' });
}

test('prints the approved tip and total examples', () => {
  for (const [bill, percent, expected] of [
    ['50', '20', 'Tip: $10.00  Total: $60.00\n'],
    ['10.05', '10', 'Tip: $1.01  Total: $11.06\n'],
    ['10.005', '0', 'Tip: $0.00  Total: $10.01\n'],
    ['0', '0', 'Tip: $0.00  Total: $0.00\n'],
    ['0', '20', 'Tip: $0.00  Total: $0.00\n'],
    ['50', '0', 'Tip: $0.00  Total: $50.00\n'],
  ]) {
    const result = run(bill, '--percent', percent);
    assert.equal(result.status, 0, `${bill}, ${percent}: ${result.stderr}`);
    assert.equal(result.stdout, expected);
    assert.equal(result.stderr, '');
  }
});

test('rejects invalid input without printing a result', () => {
  for (const args of [
    [], ['50'], ['50', '--percent'], ['50', '--percent', '20', 'extra'],
    ['50', '--percent', '20', '--percent', '10'],
    ['50', '--split', '3'],
    ['-1', '--percent', '20'], ['1x', '--percent', '20'],
    ['.5', '--percent', '20'], ['1.', '--percent', '20'],
    ['50', '--percent', '-1'], ['50', '--percent', 'abc'],
    ['50', '--percent', '1e2'], ['50', '--percent', ''],
  ]) {
    const result = run(...args);
    assert.notEqual(result.status, 0, args.join(' '));
    assert.equal(result.stdout, '', args.join(' '));
    assert.match(result.stderr, /^Error: .+\n$/, args.join(' '));
  }
});

